package com.autoops.ai.tool.workflow;import com.autoops.ai.tool.AITool;import org.springframework.stereotype.Component;import java.util.Map;@Component public class ValidateWorkflowTool implements AITool{public String name(){return "validate_workflow_draft";}public ToolRisk risk(){return ToolRisk.VALIDATE;}public Map<String,Object> schema(){return Map.of("type","object","properties",Map.of("nodeCount",Map.of("type","integer")));}public Object execute(Map<String,Object>a,Long user){int n=((Number)a.getOrDefault("nodeCount",0)).intValue();return Map.of("valid",n>0,"message",n>0?"Draft contains nodes":"Workflow requires at least one node");}}
